54	// ── Shared utility functions (not schemas) ─────────────────────────────────────
55	
56	use op_state_store::{FieldSchema, FieldType, MethodDecl, PluginSchema, SideEffect};
57	use simd_json::{json, OwnedValue as Value};
58	
59	/// Materialize a deterministic initial live state from a plugin schema.
60	///
61	/// This is the schema-side bootstrap for D-Bus projection creation. It never
62	/// queries a plugin backend and never invents data outside the contract:
63	/// field defaults win, then examples, then an empty value matching the field
64	/// type. The MutationEngine writes this once when no projection exists yet;
65	/// later mutations replace it through the normal `/dev/shm/opdbus/projections`
66	/// write door.
67	pub(crate) fn materialize_state_from_schema(schema: &PluginSchema) -> Value {
68	    if let Some(example) = &schema.example {
69	        return example.clone();
70	    }
71	
72	    let mut state = simd_json::value::owned::Object::new();
73	    let mut fields = schema.fields.iter().collect::<Vec<_>>();
74	    fields.sort_by(|(a, _), (b, _)| a.cmp(b));
75	
76	    for (name, field) in fields {
77	        state.insert(name.clone(), materialize_field(field));
78	    }
79	
80	    Value::Object(Box::new(state))
81	}
82	
83	fn materialize_field(field: &FieldSchema) -> Value {
84	    if let Some(value) = &field.default {
85	        return value.clone();
86	    }
87	    if let Some(value) = &field.example {
88	        return value.clone();
89	    }
90	
91	    materialize_field_type(&field.field_type)
92	}
93	
94	fn materialize_field_type(field_type: &FieldType) -> Value {
95	    match field_type {
96	        FieldType::String => json!(""),
97	        FieldType::Integer => json!(0),
98	        FieldType::Float => json!(0.0),
99	        FieldType::Boolean => json!(false),
100	        FieldType::Array(_) => json!([]),
101	        FieldType::Object(fields) => {
102	            let mut object = simd_json::value::owned::Object::new();
103	            let mut fields = fields.iter().collect::<Vec<_>>();
104	            fields.sort_by(|(a, _), (b, _)| a.cmp(b));
105	            for (name, field) in fields {
106	                object.insert(name.clone(), materialize_field(field));
107	            }
108	            Value::Object(Box::new(object))
109	        }
110	        FieldType::Enum(values) => values
111	            .first()
112	            .map(|value| json!(value))
113	            .unwrap_or_else(|| json!(null)),
114	        FieldType::OneOf(types) => types
115	            .first()
116	            .map(materialize_field_type)
117	            .unwrap_or_else(|| json!(null)),
118	        FieldType::Any => json!(null),
119	    }
120	}
121	
122	/// Format a plugin's live state into a `PluginSchema`.
123	///
124	/// This is a *formatter*, not a schema authority — nothing here is indexed. The
125	/// plugin's live state (its `*State` struct) is the single source
126	/// of truth; field types are inferred from that state, so the schema can never
127	/// drift from what the plugin actually reports. To add a field, add it to the
128	/// plugin state — never hand-write a field definition.
129	pub(crate) fn schema_from_state(
130	    name: &str,
131	    category: &str,
132	    version: &str,
133	    description: &str,
134	    state: &Value,
135	) -> PluginSchema {
136	    use simd_json::prelude::*;
137	
138	    let mut builder = PluginSchema::builder(name)
139	        .version(version)
140	        .category(category)
141	        .description(description);
142	
143	    if let Some(obj) = state.as_object() {
144	        for (key, value) in obj.iter() {
145	            builder = builder.field(&key.to_string(), field_from_value(value));
146	        }
147	    }
148	
149	    builder.example(state.clone()).build()
150	}
151	
152	/// Infer a `FieldSchema` (type + example) from a live state value.
153	pub(crate) fn field_from_value(value: &Value) -> FieldSchema {
154	    FieldSchema {
155	        field_type: infer_field_type(value),
156	        required: false,
157	        description: String::new(),
158	        default: None,
159	        example: Some(value.clone()),
160	        constraints: Vec::new(),
161	        read_only: false,
162	        read_only_when: None,
163	    }
164	}
165	
166	/// Infer a `FieldType` from a live state value, recursing into arrays/objects.
167	pub(crate) fn infer_field_type(value: &Value) -> FieldType {
168	    use simd_json::prelude::*;
169	
170	    if value.is_null() {
171	        FieldType::Any
172	    } else if value.as_bool().is_some() {
173	        FieldType::Boolean
174	    } else if value.as_i64().is_some() || value.as_u64().is_some() {
175	        FieldType::Integer
176	    } else if value.as_f64().is_some() {
177	        FieldType::Float
178	    } else if value.as_str().is_some() {
179	        FieldType::String
180	    } else if let Some(arr) = value.as_array() {
181	        let inner = arr.first().map(infer_field_type).unwrap_or(FieldType::Any);
182	        FieldType::Array(Box::new(inner))
183	    } else if let Some(obj) = value.as_object() {
184	        let fields = obj
185	            .iter()
186	            .map(|(k, v)| (k.to_string(), field_from_value(v)))
187	            .collect();
188	        FieldType::Object(fields)
189	    } else {
190	        FieldType::Any
191	    }
192	}
193	
194	pub(crate) fn any_field(required: bool, description: &str, default: Option<Value>) -> FieldSchema {
195	    FieldSchema {
196	        field_type: FieldType::Any,
197	        required,
198	        description: description.to_string(),
199	        default,
200	        example: None,
201	        constraints: Vec::new(),
202	        read_only: false,
203	        read_only_when: None,
204	    }
205	}
206	
207	pub(crate) fn cap_method(
208	    name: &str,
209	    side_effect: SideEffect,
210	    idempotent: bool,
211	    required_capability: &str,
212	    subid: &str,
213	) -> MethodDecl {
214	    MethodDecl {
215	        name: name.to_string(),
216	        args: json!({"type": "object", "additionalProperties": true}),
217	        returns: Some(json!({"type": "object", "additionalProperties": true})),
218	        side_effect,
219	        idempotent,
220	        required_capability: Some(required_capability.to_string()),
221	        subid: subid.to_string(),
222	    }
223	}
224	
225	/// Create a MethodDecl from a schemars-typed input struct.
226	///
227	/// This is the canonical pattern for all plugins: define method inputs as
228	/// Rust structs with `#[derive(schemars::JsonSchema)]`, then use this function
229	/// to generate typed method declarations. The resulting schema drives D-Bus method
230	/// validation and gRPC proto generation.
231	pub fn method_decl_from_schemars<Input: schemars::JsonSchema>(
232	    name: &str,
233	    side_effect: SideEffect,
234	    idempotent: bool,
235	    required_capability: &str,
236	    subid: &str,
237	) -> MethodDecl {
238	    let serde_schema = serde_json::to_value(schemars::schema_for!(Input)).unwrap();
239	    let schema_bytes = serde_json::to_vec(&serde_schema).unwrap();
240	    let mut schema_bytes = schema_bytes;
241	    let args = simd_json::to_owned_value(&mut schema_bytes).unwrap();
242	    MethodDecl {
243	        name: name.to_string(),
244	        args,
245	        returns: Some(json!({"type": "object"})),
246	        side_effect,
247	        idempotent,
248	        required_capability: Some(required_capability.to_string()),
249	        subid: subid.to_string(),
250	    }
251	}
252	
253	pub(crate) fn simple_schema(
254	    name: &str,
255	    description: &str,
256	    dependencies: &[&str],
257	    fields: Vec<(&str, FieldSchema)>,
258	) -> PluginSchema {
259	    let mut builder = PluginSchema::builder(name)
260	        .version("1.0.0")
261	        .description(description);
262	    for dep in dependencies {
263	        builder = builder.dependency(dep);
264	    }
265	    for (field_name, schema) in fields {
266	        builder = builder.field(field_name, schema);
267	    }
268	    builder.build()
269	}
270	
271	#[cfg(test)]
272	mod tests {
273	    use super::*;
274	    use std::collections::HashMap;
275	
276	    fn field(field_type: FieldType, default: Option<Value>, example: Option<Value>) -> FieldSchema {
277	        FieldSchema {
278	            field_type,
279	            required: false,
280	            description: String::new(),
281	            default,
282	            example,
283	            constraints: Vec::new(),
284	            read_only: false,
285	            read_only_when: None,
286	        }
287	    }
288	
289	    #[test]
290	    fn materializes_seed_state_from_schema_defaults_examples_and_types() {
291	        let schema = PluginSchema::builder("example")
292	            .field(
293	                "enabled",
294	                field(FieldType::Boolean, Some(json!(true)), Some(json!(false))),
295	            )
296	            .field("label", field(FieldType::String, None, Some(json!("demo"))))
297	            .field(
298	                "mode",
299	                field(
300	                    FieldType::Enum(vec!["active".to_string(), "passive".to_string()]),
301	                    None,
302	                    None,
303	                ),
304	            )
305	            .field(
306	                "choice",
307	                field(
308	                    FieldType::OneOf(vec![FieldType::Integer, FieldType::String]),
309	                    None,
310	                    None,
311	                ),
312	            )
313	            .field(
314	                "nested",
315	                field(
316	                    FieldType::Object(HashMap::from([(
317	                        "count".to_string(),
318	                        field(FieldType::Integer, None, None),
319	                    )])),
320	                    None,
321	                    None,
322	                ),
323	            )
324	            .build();
325	
326	        let state = materialize_state_from_schema(&schema);
327	
328	        assert_eq!(state["enabled"], json!(true));
329	        assert_eq!(state["label"], json!("demo"));
330	        assert_eq!(state["mode"], json!("active"));
331	        assert_eq!(state["choice"], json!(0));
332	        assert_eq!(state["nested"]["count"], json!(0));
333	    }
334	}
