1	//! Mutation Engine - The Authoritative Source for State and Schema DNA
2	//!
3	//! The Mutation Engine is the central coordinator that:
4	//! - Authoritatively routes all mutations (gRPC and D-Bus)
5	//! - Ensures all state changes are strictly recorded in the Event Chain (Audit Log)
6	//! - Broadcasts authoritative state changes to gRPC subscribers
7	//! - Directly manages authoritative RCP stores (OVSDB, NonNet, SQLite)
8	
9	use async_trait::async_trait;
10	use serde_json;
11	use simd_json::prelude::{ValueAsContainer, ValueAsMutContainer, ValueAsScalar, ValueObjectAccess};
12	use std::collections::HashMap;
13	use std::sync::Arc;
14	use tokio::sync::{broadcast, OnceCell, RwLock, Semaphore};
15	use zbus::zvariant::OwnedValue as ZOwnedValue;
16	use zbus::{Connection, Proxy};
17	
18	use base64::Engine;
19	use op_identity::{read_sled, write_sled_full};
20	use op_jsonrpc::nonnet::NonNetDb;
21	use op_network::rovs_proxy::OvsdbDbusClient;
22	use op_state_store::{ChainEvent, Decision, EventChain, MemoryStore, OperationType, StateStore};
23	
24	/// A state change projected from the authoritative system bus
25	#[derive(Debug, Clone)]
26	pub struct StateChange {
27	    pub change_id: String,
28	    pub event_id: u64,
29	    pub plugin_id: String,
30	    pub object_path: String,
31	    pub change_type: ChangeType,
32	    pub member_name: Option<String>,
33	    pub old_value: Option<simd_json::OwnedValue>,
34	    pub new_value: simd_json::OwnedValue,
35	    pub tags_touched: Vec<String>,
36	    pub event_hash: String,
37	    pub timestamp: chrono::DateTime<chrono::Utc>,
38	    pub actor_id: String,
39	    pub source: ChangeSource,
40	}
41	
42	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
43	pub enum ChangeType {
44	    PropertySet,
45	    PropertyDelete,
46	    MethodCall,
47	    Signal,
48	    ObjectAdded,
49	    ObjectRemoved,
50	    SchemaMigration,
51	}
52	
53	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
54	pub enum ChangeSource {
55	    DBus,
56	    Grpc,
57	    Internal,
58	}
59	
60	pub struct MutationEngine {
61	    /// Authoritative Event Chain
62	    pub event_chain: Arc<RwLock<EventChain>>,
63	    /// Real-time change projection channel
64	    change_tx: broadcast::Sender<StateChange>,
65	    /// State cache for instant gRPC retrieval
66	    state_cache: Arc<RwLock<HashMap<String, simd_json::OwnedValue>>>,
67	    /// System D-Bus connection authority
68	    pub dbus_connection: Arc<OnceCell<Connection>>,
69	    /// Session bus connection for projection tree introspection
70	    session_bus: Arc<OnceCell<Connection>>,
71	    /// Resource limiter for D-Bus operations
72	    #[allow(dead_code)]
73	    dbus_call_limiter: Arc<Semaphore>,
74	
75	    /// Authoritative RCP stores
76	    pub ovsdb: Arc<OvsdbDbusClient>,
77	    pub nonnet: Arc<NonNetDb>,
78	    /// In-process plugin handles for MethodCall dispatch (e.g. createunixsocket).
79	    pub unix_socket: Arc<op_plugins::state_plugins::UnixSocketPlugin>,
80	}
81	
82	impl std::fmt::Debug for MutationEngine {
83	    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
84	        f.debug_struct("MutationEngine").finish()
85	    }
86	}
87	
88	#[async_trait]
89	impl op_core::state_publisher::StatePublisher for MutationEngine {
90	    async fn publish_change(
91	        &self,
92	        plugin_id: String,
93	        path: String,
94	        change_type: op_core::state_publisher::ChangeType,
95	        property: Option<String>,
96	        old_value: Option<simd_json::OwnedValue>,
97	        new_value: simd_json::OwnedValue,
98	        tags: Vec<String>,
99	        source: String,
100	    ) -> anyhow::Result<()> {
101	        let internal_type = match change_type {
102	            op_core::state_publisher::ChangeType::PropertySet => ChangeType::PropertySet,
103	            op_core::state_publisher::ChangeType::Signal => ChangeType::Signal,
104	            op_core::state_publisher::ChangeType::Deleted => ChangeType::ObjectRemoved,
105	        };
106	
107	        self.process_authoritative_change(
108	            plugin_id,
109	            path,
110	            internal_type,
111	            property,
112	            old_value,
113	            new_value,
114	            tags,
115	            source,
116	            None,
117	            ChangeSource::Internal,
118	        )
119	        .await
120	        .map(|_| ())
121	        .map_err(|e| anyhow::anyhow!(e))
122	    }
123	}
124	
125	impl MutationEngine {
126	    /// Create a new authoritative Mutation Engine
127	    pub fn new(
128	        event_chain: Arc<RwLock<EventChain>>,
129	        ovsdb: Arc<OvsdbDbusClient>,
130	        nonnet: Arc<NonNetDb>,
131	    ) -> Self {
132	        let (change_tx, _) = broadcast::channel(1024);
133	        Self {
134	            event_chain,
135	            change_tx,
136	            state_cache: Arc::new(RwLock::new(HashMap::new())),
137	            dbus_connection: Arc::new(OnceCell::new()),
138	            session_bus: Arc::new(OnceCell::new()),
139	            dbus_call_limiter: Arc::new(Semaphore::new(32)),
140	            ovsdb,
141	            nonnet,
142	            unix_socket: Arc::new(op_plugins::state_plugins::UnixSocketPlugin::new()),
143	        }
144	    }
145	
146	    /// Seed missing plugin projection files from the canonical PluginSchema
147	    /// catalog. This runs once during bridge startup; existing projection files
148	    /// are left untouched so real mutation state always wins.
149	    pub async fn seed_missing_plugin_projections(&self) -> anyhow::Result<usize> {
150	        let state_store: Arc<dyn StateStore> = Arc::new(MemoryStore::new());
151	        let registry = op_plugins::DefaultPluginRegistry::new(state_store);
152	        let plugins = registry.load_all_plugins().await?;
153	        let mut seeded = 0usize;
154	
155	        for plugin in plugins {
156	            let plugin_id = plugin.name().to_string();
157	            if op_core::projection_shm::read_projection_bytes(&plugin_id).is_some() {
158	                continue;
159	            }
160	
161	            let Some(schema) = plugin.schema() else {
162	                tracing::debug!(
163	                    plugin_id = %plugin_id,
164	                    "Skipping projection seed for plugin without PluginSchema"
165	                );
166	                continue;
167	            };
168	
169	            if schema.name != plugin_id {
170	                tracing::warn!(
171	                    plugin_id = %plugin_id,
172	                    schema_name = %schema.name,
173	                    "Skipping projection seed for schema owned by a different plugin"
174	                );
175	                continue;
176	            }
177	
178	            let seed_state = op_plugins::projection_seed_state_from_schema(&schema);
179	            let json = simd_json::to_string(&seed_state)?;
180	            op_core::projection_shm::write_projection(&plugin_id, json.as_bytes())?;
181	            self.update_state_cache(plugin_id.clone(), seed_state).await;
182	            seeded += 1;
183	        }
184	
185	        tracing::info!(
186	            count = seeded,
187	            "Seeded missing plugin projections from PluginSchema"
188	        );
189	        Ok(seeded)
190	    }
191	
192	    /// Authoritative D-Bus connection getter
193	    pub async fn dbus_connection(&self) -> anyhow::Result<Connection> {
194	        self.dbus_connection
195	            .get_or_try_init(|| async { Connection::system().await })
196	            .await
197	            .cloned()
198	            .map_err(|e| anyhow::anyhow!(e))
199	    }
200	
201	    /// Get or create the session bus connection (for projection tree introspection)
202	    async fn session_bus(&self) -> anyhow::Result<Connection> {
203	        self.session_bus
204	            .get_or_try_init(|| async {
205	                let addr = std::env::var("DBUS_SESSION_BUS_ADDRESS")
206	                    .unwrap_or_else(|_| op_core::config::SESSION_BUS_ADDRESS.to_string());
207	                zbus::connection::Builder::address(addr.as_str())
208	                    .map_err(|e| anyhow::anyhow!("Builder::address: {}", e))?
209	                    .build()
210	                    .await
211	                    .map_err(|e| anyhow::anyhow!("Session bus connect: {}", e))
212	            })
213	            .await
214	            .cloned()
215	            .map_err(|e| anyhow::anyhow!(e))
216	    }
217	
218	    /// Crawl the D-Bus projection tree for a plugin and return its full state
219	    /// as JSON. Introspects `/org/opdbus/v1/plugins/<plugin_id>`, recursively
220	    /// descends child nodes, and reads all properties from all interfaces.
221	    async fn crawl_plugin_dbus_tree(&self, plugin_id: &str) -> Option<simd_json::OwnedValue> {
222	        let conn = match self.session_bus().await {
223	            Ok(c) => c,
224	            Err(e) => {
225	                tracing::debug!(error = %e, "session bus unavailable for crawl");
226	                return None;
227	            }
228	        };
229	
230	        let root_path = format!("/org/opdbus/v1/plugins/{}", plugin_id);
231	        let bus_name = "org.opdbus.v1.plugins";
232	
233	        let mut result = simd_json::value::owned::Object::new();
234	        Self::crawl_path(&conn, bus_name, &root_path, &mut result).await;
235	        if result.is_empty() {
236	            None
237	        } else {
238	            Some(simd_json::OwnedValue::Object(Box::new(result)))
239	        }
240	    }
241	
242	    /// Recursively introspect a D-Bus path, reading properties and descending
243	    /// into child nodes.
244	    async fn crawl_path(
245	        conn: &Connection,
246	        bus_name: &str,
247	        path: &str,
248	        out: &mut simd_json::value::owned::Object,
249	    ) {
250	        // Introspect to discover interfaces and child nodes
251	        let introspect_xml: String = match conn
252	            .call_method(
253	                Some(bus_name),
254	                path,
255	                Some("org.freedesktop.DBus.Introspectable"),
256	                "Introspect",
257	                &(),
258	            )
259	            .await
260	        {
261	            Ok(msg) => msg.body().deserialize::<String>().unwrap_or_default(),
262	            Err(e) => {
263	                tracing::debug!(path = %path, error = %e, "introspect failed");
264	                return;
265	            }
266	        };
267	
268	        // Parse the introspection XML for interfaces and child nodes
269	        let interfaces = Self::parse_interfaces(&introspect_xml);
270	        let child_nodes = Self::parse_child_nodes(&introspect_xml);
271	
272	        // Read properties from each non-standard interface
273	        for iface in &interfaces {
274	            // Skip standard D-Bus interfaces
275	            if iface.starts_with("org.freedesktop.DBus.") {
276	                continue;
277	            }
278	
279	            let props: std::collections::HashMap<String, zbus::zvariant::OwnedValue> = match conn
280	                .call_method(
281	                    Some(bus_name),
282	                    path,
283	                    Some("org.freedesktop.DBus.Properties"),
284	                    "GetAll",
285	                    &iface,
286	                )
287	                .await
288	            {
289	                Ok(msg) => msg
290	                    .body()
291	                    .deserialize::<std::collections::HashMap<String, zbus::zvariant::OwnedValue>>()
292	                    .unwrap_or_default(),
293	                Err(_) => std::collections::HashMap::new(),
294	            };
295	
296	            let mut iface_obj = simd_json::value::owned::Object::new();
297	            for (prop_name, prop_val) in &props {
298	                // zvariant::OwnedValue serializes as {"signature":"s","value":"..."}
299	                // Extract just the value field for a clean JSON projection.
300	                let json_val: serde_json::Value =
301	                    serde_json::to_value(prop_val).unwrap_or(serde_json::Value::Null);
302	                let extracted = json_val.get("value").unwrap_or(&json_val);
303	                let json_str =
304	                    serde_json::to_string(extracted).unwrap_or_else(|_| "null".to_string());
305	                let mut bytes = json_str.into_bytes();
306	                if let Ok(v) = simd_json::to_owned_value(&mut bytes) {
307	                    iface_obj.insert(prop_name.clone(), v);
308	                }
309	            }
310	            if !iface_obj.is_empty() {
311	                out.insert(
312	                    iface.clone(),
313	                    simd_json::OwnedValue::Object(Box::new(iface_obj)),
314	                );
315	            }
316	        }
317	
318	        // Recurse into child nodes
319	        for child in &child_nodes {
320	            let child_path = format!("{}/{}", path.trim_end_matches('/'), child);
321	            let mut child_obj = simd_json::value::owned::Object::new();
322	            Box::pin(Self::crawl_path(
323	                conn,
324	                bus_name,
325	                &child_path,
326	                &mut child_obj,
327	            ))
328	            .await;
329	            if !child_obj.is_empty() {
330	                out.insert(
331	                    child.clone(),
332	                    simd_json::OwnedValue::Object(Box::new(child_obj)),
333	                );
334	            }
335	        }
336	    }
337	
338	    /// Parse interface names from D-Bus introspection XML
339	    fn parse_interfaces(xml: &str) -> Vec<String> {
340	        let mut interfaces = Vec::new();
341	        for line in xml.lines() {
342	            let trimmed = line.trim();
343	            if let Some(rest) = trimmed.strip_prefix("<interface name=\"") {
344	                if let Some(end) = rest.find("\">") {
345	                    interfaces.push(rest[..end].to_string());
346	                }
347	            }
348	        }
349	        interfaces
350	    }
351	
352	    /// Parse child node names from D-Bus introspection XML
353	    fn parse_child_nodes(xml: &str) -> Vec<String> {
354	        let mut nodes = Vec::new();
355	        for line in xml.lines() {
356	            let trimmed = line.trim();
357	            if let Some(rest) = trimmed.strip_prefix("<node name=\"") {
358	                if let Some(end) = rest.find("\"") {
359	                    nodes.push(rest[..end].to_string());
360	                }
361	            }
362	        }
363	        nodes
364	    }
365	
366	    fn compute_tags(&self, plugin_id: &str, object_path: &str) -> Vec<String> {
367	        let mut tags = Vec::new();
368	        if plugin_id == "net" || object_path.contains("/ovsdb/") {
369	            tags.push("network".to_string());
370	            tags.push("ovsdb".to_string());
371	        } else if object_path.contains("/nonnet/") {
372	            tags.push("nonnet".to_string());
373	            tags.push("plugin".to_string());
374	        } else {
375	            tags.push("state".to_string());
376	            tags.push(plugin_id.to_string());
377	        }
378	        tags
379	    }
380	
381	    /// Process a change that has already happened in an authoritative store.
382	    /// This records the change in the event chain and broadcasts it to gRPC.
383	    #[allow(clippy::too_many_arguments)]
384	    pub async fn process_authoritative_change(
385	        &self,
386	        plugin_id: String,
387	        object_path: String,
388	        change_type: ChangeType,
389	        member_name: Option<String>,
390	        old_value: Option<simd_json::OwnedValue>,
391	        new_value: simd_json::OwnedValue,
392	        mut tags: Vec<String>,
393	        actor_id: String,
394	        capability_id: Option<String>,
395	        source: ChangeSource,
396	    ) -> Result<StateChange, String> {
397	        if tags.is_empty() {
398	            tags = self.compute_tags(&plugin_id, &object_path);
399	        }
400	
401	        let event = {
402	            let mut chain = self.event_chain.write().await;
403	            let op = match change_type {
404	                ChangeType::PropertySet => OperationType::PropertySet,
405	                ChangeType::ObjectRemoved => OperationType::Custom("delete".to_string()),
406	                _ => OperationType::EmitSignal,
407	            };
408	            if let Some(capability) = capability_id {
409	                let event = ChainEvent::new(
410	                    chain.next_event_id(),
411	                    chain.last_hash().to_string(),
412	                    actor_id.clone(),
413	                    plugin_id.clone(),
414	                    "1.0.0".to_string(),
415	                    op,
416	                    object_path.clone(),
417	                    tags.clone(),
418	                    Decision::Allow,
419	                    &new_value,
420	                )
421	                .with_capability(capability);
422	                chain.append(event).clone()
423	            } else {
424	                let event = chain.record(
425	                    actor_id.clone(),
426	                    plugin_id.clone(),
427	                    "1.0.0".to_string(),
428	                    op,
429	                    object_path.clone(),
430	                    tags.clone(),
431	                    Decision::Allow,
432	                    &new_value,
433	                );
434	                event.clone()
435	            }
436	        };
437	
438	        self.update_cached_plugin_state(
439	            &plugin_id,
440	            &object_path,
441	            change_type,
442	            member_name.as_deref(),
443	            &new_value,
444	        )
445	        .await;
446	
447	        // Write the plugin's state to the shm projection layer.
448	        //
449	        // The projection IS the state — `/dev/shm/opdbus/projections/<plugin>.json`
450	        // is the single source of truth that the D-Bus tree derives from.
451	        // We write a composite object: `data` holds the mutation value, and
452	        // `_introspection` holds the D-Bus tree crawl result. The projection
453	        // server reads `data` for the `ProjectedObject.Data` property and
454	        // derives child paths from it. The `_introspection` field (underscore-
455	        // prefixed) is skipped by path derivation so it doesn't create child
456	        // objects (no recursive echo).
457	        if change_type != ChangeType::ObjectRemoved {
458	            let crawl_result = self.crawl_plugin_dbus_tree(&plugin_id).await;
459	
460	            let projection_value = if let Some(crawl) = crawl_result {
461	                simd_json::json!({
462	                    "data": new_value,
463	                    "_introspection": crawl,
464	                })
465	            } else {
466	                new_value.clone()
467	            };
468	
469	            match simd_json::to_string(&projection_value) {
470	                Ok(json) => {
471	                    if let Err(e) =
472	                        op_core::projection_shm::write_projection(&plugin_id, json.as_bytes())
473	                    {
474	                        tracing::warn!(plugin_id = %plugin_id, error = %e, "Failed to write shm projection");
475	                    }
476	                }
477	                Err(e) => {
478	                    tracing::warn!(
479	                        plugin_id = %plugin_id,
480	                        error = %e,
481	                        "Failed to serialize plugin state for shm projection"
482	                    );
483	                }
484	            }
485	        }
486	
487	        let change = StateChange {
488	            change_id: uuid::Uuid::new_v4().to_string(),
489	            event_id: event.event_id,
490	            plugin_id,
491	            object_path,
492	            change_type,
493	            member_name,
494	            old_value,
495	            new_value,
496	            tags_touched: tags,
497	            event_hash: event.event_hash.clone(),
498	            timestamp: event.timestamp,
499	            actor_id,
500	            source,
501	        };
502	
503	        let _ = self.change_tx.send(change.clone());
504	        Ok(change)
505	    }
