507	    /// Start the Mutation Engine background tasks.
508	    /// Subscribes to authoritative RCP stores and broadcasts changes.
509	    pub async fn start(self: Arc<Self>) -> anyhow::Result<()> {
510	        let me = self.clone();
511	
512	        // 1. Subscribe to NonNet updates
513	        let mut nonnet_rx = self.nonnet.subscribe();
514	        let nonnet_self = me.clone();
515	        tokio::spawn(async move {
516	            loop {
517	                match nonnet_rx.recv().await {
518	                    Ok(update) => {
519	                        let _ = nonnet_self
520	                            .process_authoritative_change(
521	                                update.table.clone(),
522	                                format!(
523	                                    "/org/opdbus/v1/nonnet/{}/{}",
524	                                    update.db_name, update.table
525	                                ),
526	                                ChangeType::PropertySet,
527	                                None,
528	                                None,
529	                                simd_json::json!(update.rows),
530	                                vec!["nonnet".to_string()],
531	                                "nonnet-db".to_string(),
532	                                None,
533	                                ChangeSource::Internal,
534	                            )
535	                            .await;
536	                    }
537	                    Err(tokio::sync::broadcast::error::RecvError::Lagged(n)) => {
538	                        tracing::warn!("NonNet subscription lagged by {} events", n);
539	                    }
540	                    Err(tokio::sync::broadcast::error::RecvError::Closed) => break,
541	                }
542	            }
543	        });
544	
545	        // 2. Subscribe to OVSDB updates
546	        let ovsdb_self = me.clone();
547	        tokio::spawn(async move {
548	            if let Ok(mut rx) = ovsdb_self.ovsdb.monitor_db("Open_vSwitch").await {
549	                loop {
550	                    match rx.recv().await {
551	                        Ok(update) => {
552	                            if let Some(params) = update.get("params").and_then(|p| p.as_array()) {
553	                                if params.len() >= 3 {
554	                                    if let Some(tables) = params[2].as_object() {
555	                                        for (table_name, table_update) in tables.iter() {
556	                                            let table_name_owned: String = table_name.to_string();
557	                                            // monitor_db returns serde_json::Value; convert to
558	                                            // simd_json::OwnedValue required by process_authoritative_change.
559	                                            let simd_val: simd_json::OwnedValue = {
560	                                                match serde_json::to_string(table_update)
561	                                                    .ok()
562	                                                    .and_then(|s| {
563	                                                        let mut b = s.into_bytes();
564	                                                        simd_json::to_owned_value(&mut b).ok()
565	                                                    }) {
566	                                                    Some(v) => v,
567	                                                    None => continue,
568	                                                }
569	                                            };
570	                                            let _ = ovsdb_self
571	                                                .process_authoritative_change(
572	                                                    "net".to_string(),
573	                                                    format!(
574	                                                        "/org/opdbus/v1/ovsdb/{}",
575	                                                        table_name_owned
576	                                                    ),
577	                                                    ChangeType::PropertySet,
578	                                                    Some(table_name_owned),
579	                                                    None,
580	                                                    simd_val,
581	                                                    vec![
582	                                                        "ovsdb".to_string(),
583	                                                        "network".to_string(),
584	                                                    ],
585	                                                    "ovsdb-monitor".to_string(),
586	                                                    None,
587	                                                    ChangeSource::DBus,
588	                                                )
589	                                                .await;
590	                                        }
591	                                    }
592	                                }
593	                            }
594	                        }
595	                        Err(tokio::sync::broadcast::error::RecvError::Lagged(n)) => {
596	                            tracing::warn!("OVSDB subscription lagged by {} events", n);
597	                            continue;
598	                        }
599	                        Err(tokio::sync::broadcast::error::RecvError::Closed) => break,
600	                    }
601	                }
602	            }
603	        });
604	
605	        Ok(())
606	    }
