608	    /// Unified mutation entry point. Writes to authoritative RCP stores and
609	    /// triggers the event recording/broadcast pipeline.
610	    #[allow(clippy::too_many_arguments)]
611	    pub async fn mutate(
612	        &self,
613	        plugin_id: String,
614	        object_path: String,
615	        change_type: ChangeType,
616	        member_name: Option<String>,
617	        value: simd_json::OwnedValue,
618	        actor_id: String,
619	        capability_id: Option<String>,
620	    ) -> anyhow::Result<MutationResult> {
621	        let mut old_value = None;
622	        let mut authoritative_value = value.clone();
623	
624	        // Resolve the acting identity from the Sled (/dev/shm/plugin_schema.dat)
625	        // when the caller omitted it. The Sled carries the WireGuard footprint +
626	        // trace_id — that identity is authoritative for every mutation.
627	        let actor_id = if actor_id.is_empty() {
628	            sled_footprint().unwrap_or_else(|| "anonymous".to_string())
629	        } else {
630	            actor_id
631	        };
632	
633	        // 1. Write to authoritative RCP store
634	        if plugin_id == "net" || object_path.contains("/ovsdb/") {
635	            // OVSDB Authoritative Path
636	            if change_type == ChangeType::MethodCall {
637	                if let Some(method) = &member_name {
638	                    match method.as_str() {
639	                        "create_bridge" => {
640	                            if let Some(name) = value.as_str() {
641	                                self.ovsdb.create_bridge(name).await?;
642	                            }
643	                        }
644	                        "add_port" => {
645	                            if let Some(args) = value.as_array() {
646	                                if args.len() >= 2 {
647	                                    if let (Some(br), Some(port)) =
648	                                        (args[0].as_str(), args[1].as_str())
649	                                    {
650	                                        self.ovsdb.add_port(br, port).await?;
651	                                    }
652	                                }
653	                            }
654	                        }
655	                        _ => {
656	                            // Fallback to generic D-Bus call if it's a known service
657	                            let _ = self
658	                                .call_dbus_method(
659	                                    &format!("org.opdbus.{}.v1", plugin_id),
660	                                    &object_path,
661	                                    "org.opdbus.OvsdbV1",
662	                                    method,
663	                                    vec![value.clone()],
664	                                    &actor_id,
665	                                    &capability_id,
666	                                )
667	                                .await?;
668	                        }
669	                    }
670	                }
671	            } else if change_type == ChangeType::PropertySet {
672	                if let Some(prop) = &member_name {
673	                    // Extract bridge name from path if possible
674	                    // Path format: /org/opdbus/v1/ovsdb/Bridge/bridge_name
675	                    let parts: Vec<&str> = object_path.split('/').collect();
676	                    if parts.len() >= 6 && parts[4] == "Bridge" {
677	                        let br_name = parts[5].replace('_', "-");
678	                        if let Some(val_str) = value.as_str() {
679	                            self.ovsdb
680	                                .set_bridge_property(&br_name, prop, val_str)
681	                                .await?;
682	                        }
683	                    }
684	                }
685	            }
686	        } else if plugin_id == "unix_socket" && change_type == ChangeType::MethodCall {
687	            // unix_socket plugin dispatch: createunixsocket <name> <ports csv/vec>.
688	            // The method registers the name+ports routing tag against the
689	            // shared container.sock transport; the transport owner is not
690	            // replaced during registration.
691	            if let Some(method) = &member_name {
692	                if method == "createunixsocket" {
693	                    let (name, ports) = parse_socket_args(&value);
694	                    let result = self
695	                        .unix_socket
696	                        .create_unix_socket(name.clone(), ports.clone());
697	                    if !result.success {
698	                        anyhow::bail!(result.errors.join("; "));
699	                    }
700	                    authoritative_value = unix_socket_state_after_registration(&name, &ports);
701	                }
702	            }
703	        } else {
704	            // NonNet / Generic Plugin Path
705	            if change_type == ChangeType::PropertySet {
706	                // Get old value for the footprint before update from cache
707	                old_value = self.get_state(&plugin_id).await.and_then(|v| {
708	                    if let Some(prop) = &member_name {
709	                        v.get(prop).cloned()
710	                    } else {
711	                        Some(v)
712	                    }
713	                });
714	
715	                // For NonNet plugins, we update the NonNetDb which is authoritative for non-network state
716	                if let Some(rows) = value.as_array() {
717	                    let rows_vec: Vec<simd_json::OwnedValue> = rows.to_vec();
718	                    self.nonnet.update_table(&plugin_id, rows_vec).await;
719	                }
720	            }
721	        }
722	
723	        // 2. Record and broadcast change
724	        let change = self
725	            .process_authoritative_change(
726	                plugin_id,
727	                object_path,
728	                change_type,
729	                member_name,
730	                old_value,
731	                authoritative_value.clone(),
732	                vec![], // Automatically computed in process_authoritative_change
733	                actor_id,
734	                capability_id,
735	                ChangeSource::Grpc,
736	            )
737	            .await
738	            .map_err(|e| anyhow::anyhow!(e))?;
739	
740	        // Write the Identity Sled with the updated mutation index.
741	        {
742	            let (existing_pubkey_b64, existing_trace_hex) = if let Ok((ptr, _mmap)) = read_sled() {
743	                unsafe {
744	                    let sled = &*ptr;
745	                    (
746	                        base64::engine::general_purpose::STANDARD.encode(sled.wireguard_pubkey),
747	                        sled.trace_id_hex(),
748	                    )
749	                }
750	            } else {
751	                (String::new(), String::new())
752	            };
753	            if let Err(e) =
754	                write_sled_full(&existing_pubkey_b64, change.event_id, &existing_trace_hex)
755	            {
756	                tracing::warn!("sled write after mutation failed: {}", e);
757	            }
758	        }
759	
760	        Ok(MutationResult {
761	            success: true,
762	            event_id: change.event_id,
763	            event_hash: change.event_hash,
764	            result: Some(authoritative_value),
765	            error: None,
766	        })
767	    }
