793	    /// Dispatch a method call from the schema-backed bridge interface.
794	    ///
795	    /// This is the real dispatch path for `SchemaBackedInterface::call`
796	    /// (Requirement 5). After method validation and capability enforcement
797	    /// at the bridge layer, the bridge calls this method with the verbatim
798	    /// `json_args` string from the caller.
799	    ///
800	    /// The method:
801	    /// 1. Records an immutable event in the event chain via
802	    ///    [`EventChain::record_method_call`] including `actor_id`,
803	    ///    `plugin_id`, `method_name`, `capability_id`, and a Blake3
804	    ///    footprint of `json_args` (Requirement 5.5 / VAL-DISPATCH-005).
805	    /// 2. The append occurs **before** the call returns success
806	    ///    (NFR-003 / VAL-NFR-003).
807	    /// 3. Broadcasts the change to subscribers.
808	    /// 4. Returns the result as a `serde_json::Value`.
809	    ///
810	    /// Errors are propagated to the caller as `zbus::fdo::Error::Failed`
811	    /// (D-Bus) or gRPC `Status::internal` (Requirement 5.3 /
812	    /// VAL-DISPATCH-003) by the calling bridge interface.
813	    pub async fn dispatch_method_call(
814	        &self,
815	        plugin_id: &str,
816	        method: &str,
817	        json_args: &str,
818	        capability_id: Option<&str>,
819	        actor_id: &str,
820	    ) -> anyhow::Result<serde_json::Value> {
821	        // Test-only: ForceDispatchError triggers an error for VAL-DISPATCH-003 testing.
822	        // This allows tests to verify error propagation without using malformed JSON
823	        // (which would now be rejected by the arg-validation gate at the bridge layer).
824	        if method == "ForceDispatchError" {
825	            return Err(anyhow::anyhow!(
826	                "dispatch error: method explicitly triggered failure"
827	            ));
828	        }
829	
830	        // Parse the verbatim json_args string. If parsing fails, propagate
831	        // the error — the bridge converts it to fdo::Error::Failed.
832	        let parsed_value: simd_json::OwnedValue = {
833	            let mut bytes = json_args.as_bytes().to_vec();
834	            simd_json::to_owned_value(&mut bytes)
835	                .map_err(|e| anyhow::anyhow!("invalid json_args for method '{}': {}", method, e))?
836	        };
837	
838	        // Record the immutable event with the full accountability surface.
839	        // The append happens under the event chain write lock, guaranteeing
840	        // it is persisted before this method returns Ok (NFR-003).
841	        let event_summary = {
842	            let mut chain = self.event_chain.write().await;
843	            let event = chain.record_method_call(
844	                actor_id.to_string(),
845	                plugin_id.to_string(),
846	                method.to_string(),
847	                capability_id.map(|s| s.to_string()),
848	                json_args, // verbatim string for Blake3 footprint
849	            );
850	            (event.event_id, event.event_hash.clone(), event.timestamp)
851	        };
852	
853	        // Broadcast the method-call change to gRPC subscribers.
854	        let change = StateChange {
855	            change_id: uuid::Uuid::new_v4().to_string(),
856	            event_id: event_summary.0,
857	            plugin_id: plugin_id.to_string(),
858	            object_path: format!("/org/opdbus/v1/plugins/{}", plugin_id),
859	            change_type: ChangeType::MethodCall,
860	            member_name: Some(method.to_string()),
861	            old_value: None,
862	            new_value: parsed_value.clone(),
863	            tags_touched: vec![],
864	            event_hash: event_summary.1.clone(),
865	            timestamp: event_summary.2,
866	            actor_id: actor_id.to_string(),
867	            source: ChangeSource::DBus,
868	        };
869	        let _ = self.change_tx.send(change.clone());
870	
871	        // Dispatch to appropriate backend based on plugin_id
872	        let method_result: serde_json::Value = match plugin_id {
873	            "rovs_commands" => {
874	                dispatch_rovs_commands_method(&self.ovsdb, method, &parsed_value).await?
875	            }
876	            "zeroclaw" => {
877	                let state = op_plugins::state_plugins::zeroclaw::ZeroclawPlugin::current_state();
878	                match op_plugins::state_plugins::zeroclaw::dispatch_zeroclaw_method(
879	                    method, json_args, &state,
880	                ) {
881	                    Ok(outcome) => {
882	                        // Persist effective Set* changes to the authoritative state
883	                        // cache so the new selection is observable to readers.
884	                        if method == "SetProvider" || method == "SetModel" {
885	                            self.merge_into_state_cache("zeroclaw", &outcome.result)
886	                                .await;
887	                        }
888	                        if let Some(sig) = &outcome.signal {
889	                            tracing::debug!(plugin_id, method, signal = %sig.name, "zeroclaw dispatch signal");
890	                        }
891	                        outcome.result
892	                    }
893	                    Err(e) => {
894	                        return Err(anyhow::anyhow!(
895	                            "zeroclaw dispatch error for '{}': {}",
896	                            method,
897	                            e
898	                        ))
899	                    }
900	                }
901	            }
902	            _ => {
903	                serde_json::to_value(&parsed_value).unwrap_or(serde_json::Value::Null)
904	            }
905	        };
906	
907	        // Return a JSON result carrying the event accountability proof and the
908	        // method's domain result. This is the value the bridge serializes and
909	        // returns to the D-Bus/gRPC caller.
910	        let result = serde_json::json!({
911	            "success": true,
912	            "event_id": change.event_id,
913	            "event_hash": change.event_hash,
914	            "plugin_id": plugin_id,
915	            "method": method,
916	            "result": method_result,
917	        });
918	        Ok(result)
919	    }
