921	    /// Merge a flat JSON object of changed fields into the authoritative
922	    /// in-memory state cache for `plugin_id` (used to persist Zeroclaw `Set*`
923	    /// selection changes so readers observe the new effective state).
924	    async fn merge_into_state_cache(&self, plugin_id: &str, changes: &serde_json::Value) {
925	        let changes_obj = match changes.as_object() {
926	            Some(o) => o,
927	            None => return,
928	        };
929	        let mut current = self
930	            .get_state(plugin_id)
931	            .await
932	            .and_then(|v| serde_json::to_value(&v).ok())
933	            .unwrap_or_else(|| serde_json::json!({}));
934	        if let Some(cur_obj) = current.as_object_mut() {
935	            for (k, v) in changes_obj {
936	                cur_obj.insert(k.clone(), v.clone());
937	            }
938	        }
939	        let mut bytes = serde_json::to_vec(&current).unwrap_or_default();
940	        if let Ok(owned) = simd_json::to_owned_value(&mut bytes) {
941	            self.update_state_cache(plugin_id.to_string(), owned).await;
942	        }
943	    }
944	
945	    /// Fetch current state for a specific plugin from authoritative cache
946	    pub async fn get_state(&self, plugin_id: &str) -> Option<simd_json::OwnedValue> {
947	        let cache = self.state_cache.read().await;
948	        cache.get(plugin_id).cloned()
949	    }
