951	    /// Update the authoritative state cache
952	    pub async fn update_state_cache(&self, plugin_id: String, state: simd_json::OwnedValue) {
953	        let mut cache = self.state_cache.write().await;
954	        cache.insert(plugin_id, state);
955	    }
956	
957	    async fn update_cached_plugin_state(
958	        &self,
959	        plugin_id: &str,
960	        object_path: &str,
961	        change_type: ChangeType,
962	        property: Option<&str>,
963	        new_value: &simd_json::OwnedValue,
964	    ) {
965	        if object_path.starts_with("schema/") {
966	            return;
967	        }
968	
969	        let mut cache = self.state_cache.write().await;
970	
971	        match change_type {
972	            ChangeType::ObjectRemoved => {
973	                cache.remove(plugin_id);
974	            }
975	            ChangeType::PropertySet => {
976	                if let Some(property) = property {
977	                    let entry = cache
978	                        .entry(plugin_id.to_string())
979	                        .or_insert_with(|| simd_json::json!({}));
980	
981	                    if let Some(existing) = entry.as_object_mut() {
982	                        existing.insert(property.to_string(), new_value.clone());
983	                    } else {
984	                        let mut state = simd_json::value::owned::Object::new();
985	                        state.insert(property.to_string(), new_value.clone());
986	                        *entry = simd_json::OwnedValue::Object(Box::new(state));
987	                    }
988	                } else {
989	                    cache.insert(plugin_id.to_string(), new_value.clone());
990	                }
991	            }
992	            _ => {}
993	        }
994	    }
