996	    /// Route a D-Bus method call through the authoritative bridge
997	    #[allow(clippy::too_many_arguments)]
998	    pub async fn call_dbus_method(
999	        &self,
1000	        bus_name: &str,
1001	        path: &str,
1002	        interface: &str,
1003	        method: &str,
1004	        _args: Vec<simd_json::OwnedValue>,
1005	        _actor_id: &str,
1006	        capability_id: &Option<String>,
1007	    ) -> anyhow::Result<simd_json::OwnedValue> {
1008	        tracing::debug!(
1009	            bus_name,
1010	            path,
1011	            interface,
1012	            method,
1013	            capability_id = ?capability_id,
1014	            "Routing D-Bus method call through authoritative bridge"
1015	        );
1016	        let conn = self.dbus_connection().await?;
1017	        let proxy = Proxy::new(&conn, bus_name, path, interface).await?;
1018	        let result: ZOwnedValue = proxy.call(method, &()).await?;
1019	        simd_json::serde::to_owned_value(&result).map_err(|e| anyhow::anyhow!(e))
1020	    }
