1102	        .get("sockets")
1103	        .and_then(|value| value.as_array())
1104	        .or_else(|| {
1105	            state
1106	                .get("data")
1107	                .and_then(|data| data.get("sockets"))
1108	                .and_then(|value| value.as_array())
1109	        });
1110	
1111	    sockets
1112	        .into_iter()
1113	        .flatten()
1114	        .filter(|socket| {
1115	            let has_name = socket
1116	                .get("name")
1117	                .and_then(|value| value.as_str())
1118	                .map(|name| !name.is_empty())
1119	                .unwrap_or(false);
1120	            let has_path = socket
1121	                .get("path")
1122	                .and_then(|value| value.as_str())
1123	                .is_some();
