1197	/// Parse createunixsocket arguments. Accepts either a JSON array
1198	/// `[name, [ports...]]` or an object `{ "name": "...", "ports": [...] }`.
1199	/// `ports` may be a JSON array of numbers or a CSV string ("6334" / "6334,8080").
1200	fn parse_socket_args(value: &simd_json::OwnedValue) -> (String, Vec<u16>) {
