1202	        return parse_socket_arg_object(obj);
1203	    }
1204	    if let Some(arr) = value.as_array() {
1205	        if arr.len() == 1 {
1206	            if let Some(obj) = arr.first().and_then(|v| v.as_object()) {
1207	                return parse_socket_arg_object(obj);
1208	            }
1209	        }
1210	        let name = arr
1211	            .first()
1212	            .and_then(|v| v.as_str())
1213	            .unwrap_or("")
1214	            .to_string();
1215	        let ports = parse_ports_value(arr.get(1));
