1231	fn parse_ports_value(value: Option<&simd_json::OwnedValue>) -> Vec<u16> {
1232	    let Some(v) = value else {
1233	        return Vec::new();
1234	    };
1235	    if let Some(arr) = v.as_array() {
1236	        return arr
1237	            .iter()
1238	            .filter_map(parse_port_number)
1239	            .map(|n| n as u16)
1240	            .collect();
1241	    }
1242	    if let Some(s) = v.as_str() {
1243	        return s
1244	            .split(',')
1245	            .filter_map(|p| p.trim().parse::<u16>().ok())
1246	            .collect();
1247	    }
1248	    if let Some(n) = parse_port_number(v) {
1249	        return vec![n as u16];
1250	    }
1251	    Vec::new()
1252	}
