1254	fn parse_port_number(value: &simd_json::OwnedValue) -> Option<u64> {
1255	    value
1256	        .as_u64()
1257	        .or_else(|| value.as_i64().and_then(|n| (n >= 0).then_some(n as u64)))
1258	        .or_else(|| {
1259	            value.as_f64().and_then(|n| {
1260	                (n.is_finite() && n >= 0.0 && n <= u16::MAX as f64).then_some(n as u64)
1261	            })
1262	        })
1263	}
