268	    s.split(['_', '-', ' ', '.'])
269	        .map(|word| {
270	            let mut chars = word.chars();
271	            match chars.next() {
272	                None => String::new(),
273	                Some(first) => first.to_uppercase().chain(chars).collect(),
274	            }
275	        })
276	        .collect()
277	}
278	
279	/// Convert string to snake_case
280	#[cfg(test)]
281	fn to_snake_case(s: &str) -> String {
282	    let mut result = String::new();
283	    for (i, c) in s.chars().enumerate() {
284	        if c.is_uppercase() && i > 0 {
285	            result.push('_');
286	        }
287	        result.push(c.to_lowercase().next().unwrap_or(c));
288	    }
289	    result
290	}
