295	
296	    #[test]
297	    fn test_to_pascal_case() {
298	        assert_eq!(to_pascal_case("lxc"), "Lxc");
299	        assert_eq!(to_pascal_case("network_interface"), "NetworkInterface");
300	        assert_eq!(to_pascal_case("ovs-bridge"), "OvsBridge");
