1	//! ovs-attach — D-Bus client that calls BringUpLoopback and AttachPort
2	//! for container bootstrap.
3	//!
4	//! Discovers all config from the D-Bus tree under:
5	//! - /org/opdbus/v1/plugins/oci (loopback_required, port_attach per container)
6	//! - /org/opdbus/v1/plugins/privacy_router (bridge, port, IPs — fallback)
7	//!
8	//! No hardcoded bus names, paths, or IP addresses. The schema IS the config.
9	
10	use anyhow::{Context, Result};
11	use serde_json::Value;
12	use std::path::Path;
13	use std::process::Command;
14	use std::thread;
15	use std::time::Duration;
16	use zbus::connection::Builder;
17	
18	const DBUS_SOCKET: &str = "/run/op-dbus.sock";
19	const PLUGIN_BUS: &str = op_core::config::OPDBUS_BUS_NAME;
20	const PRIVACY_ROUTER_BASE: &str = "/org/opdbus/v1/plugins/privacy_router";
21	const OCI_BASE: &str = "/org/opdbus/v1/plugins/oci";
22	
23	async fn get_json_property(conn: &zbus::Connection, path: &str, prop: &str) -> Result<Value> {
24	    let iface = "org.opdbus.ProjectedObjectV1".to_string();
25	    let msg = conn
26	        .call_method(
27	            Some(PLUGIN_BUS),
28	            path,
29	            Some("org.freedesktop.DBus.Properties"),
30	            "Get",
31	            &(&iface, prop),
32	        )
33	        .await?;
34	    let body = msg.body();
35	    let reply: zbus::zvariant::Value = body.deserialize()?;
36	
37	    if let zbus::zvariant::Value::Str(s) = reply {
38	        Ok(serde_json::from_str(&s)?)
39	    } else {
40	        anyhow::bail!("expected string property, got {:?}", reply)
41	    }
42	}
