1	//! `blockchain` StatePlugin — exposes the live streaming-blockchain audit chain
2	//! (`op-blockchain`) through the `org.dbus.v1.plugins` surface, reachable over
3	//! `PluginService.CallMethod`.
4	//!
5	//! This is the correct home for the capability the Lovable frontend mistakenly
6	//! called as a standalone `operation.blockchain.v1.BlockchainService` gRPC
7	//! package — there is no such proto and there must not be one. New backend
8	//! capabilities register here as plugins; the served gRPC surface stays the one
9	//! shared route-builder.
10	//!
11	//! Every read is live: the plugin's live state
12	//! opens the on-disk chain at `$OPDBUS_BLOCKCHAIN_PATH` and reports its real
13	//! snapshots, DR `current_state`, snapshot interval and retention policy.
14	//! [`create_checkpoint`](BlockchainPlugin::create_checkpoint) performs a real
15	//! `create_snapshot()` and `apply_state` writes the DR state through the chain.
16	//! Nothing here is mocked.
17	
18	use super::plugin_schema_defs::schema_from_state;
19	use anyhow::Result;
20	use async_trait::async_trait;
21	use op_blockchain::StreamingBlockchain;
22	use op_state::{
23	    ApplyResult, Checkpoint, DiffMetadata, PluginCapabilities, StateAction, StateDiff, StatePlugin,
24	};
25	use op_state_store::PluginSchema;
26	use serde::{Deserialize, Serialize};
27	use simd_json::prelude::ValueAsContainer;
28	use simd_json::{json, OwnedValue as Value};
29	use std::path::PathBuf;
30	
31	/// Default on-disk location of the streaming blockchain when
32	/// `$OPDBUS_BLOCKCHAIN_PATH` is unset.
33	const DEFAULT_BASE_PATH: &str = "/var/lib/opdbus/blockchain";
34	
35	/// Key under which the disaster-recovery "current state" blob is persisted in
36	/// the state subvolume (`StreamingBlockchain::write_current_state` writes here).
37	const CURRENT_STATE_KEY: &str = "current";
38	
39	#[derive(Debug, Clone, Serialize, Deserialize, schemars::JsonSchema)]
40	pub struct RetentionView {
41	    /// Hourly retention count.
42	    #[schemars(extend("x-oscal-subid" = "obs.software.blockchain.retention.hourly@v1"))]
43	    pub hourly: usize,
44	    /// Daily retention count.
45	    #[schemars(extend("x-oscal-subid" = "obs.software.blockchain.retention.daily@v1"))]
46	    pub daily: usize,
47	    /// Weekly retention count.
48	    #[schemars(extend("x-oscal-subid" = "obs.software.blockchain.retention.weekly@v1"))]
49	    pub weekly: usize,
50	    /// Quarterly retention count.
51	    #[schemars(extend("x-oscal-subid" = "obs.software.blockchain.retention.quarterly@v1"))]
52	    pub quarterly: usize,
53	}
54	
55	#[derive(Debug, Clone, Serialize, Deserialize, schemars::JsonSchema)]
56	pub struct SnapshotEntry {
57	    /// Snapshot name.
58	    #[schemars(extend("x-oscal-subid" = "exp.software.blockchain.snapshot.name@v1"))]
59	    pub name: String,
60	    /// Snapshot creation timestamp.
61	    #[schemars(extend("x-oscal-subid" = "exp.software.blockchain.snapshot.created@v1"))]
62	    pub created: String,
63	}
64	
65	/// Blockchain plugin state schema.
66	#[derive(Debug, Clone, Serialize, Deserialize, schemars::JsonSchema)]
67	#[schemars(extend("x-oscal-subid" = "sch.software.plugin.blockchain.schema@v1"))]
68	pub struct BlockchainState {
69	    /// `active` once the chain exists on disk, `uninitialized` before first write.
70	    #[schemars(extend("x-oscal-subid" = "obs.software.blockchain.status@v1"))]
71	    pub status: String,
72	    /// Blockchain base path.
73	    #[schemars(extend("x-oscal-subid" = "exp.software.blockchain.base-path@v1"))]
74	    pub base_path: String,
75	    /// Blockchain snapshot interval.
76	    #[schemars(extend("x-oscal-subid" = "mut.service.blockchain.snapshot-interval@v1"))]
77	    pub snapshot_interval: String,
78	    /// Blockchain retention policy.
79	    #[schemars(extend("x-oscal-subid" = "obs.service.blockchain.retention@v1"))]
80	    pub retention: RetentionView,
81	    /// Number of snapshots.
82	    #[schemars(extend("x-oscal-subid" = "exp.software.blockchain.snapshot-count@v1"))]
83	    pub snapshot_count: usize,
84	    /// List of snapshots.
85	    #[schemars(extend("x-oscal-subid" = "exp.software.blockchain.snapshots@v1"))]
86	    pub snapshots: Vec<SnapshotEntry>,
87	    /// Current blockchain state.
88	    #[schemars(skip)]
89	    #[schemars(extend("x-oscal-subid" = "obs.software.blockchain.current-state@v1"))]
90	    pub current_state: Value,
91	}
92	
93	pub struct BlockchainPlugin {
94	    base_path: PathBuf,
95	}
96	
97	impl Default for BlockchainPlugin {
